def build(seed=20261110):
    rng = random.Random(seed)
    # Позиции правильного уравнены построением: 13, 13, 12, 12. Страница теста
    # ещё и перемешивает варианты при загрузке (CLAUDE.md, правило 2).
    positions = [0] * 13 + [1] * 13 + [2] * 12 + [3] * 12
    rng.shuffle(positions)
    out = []
    for item, pos in zip(Q, positions):
        opts = list(item["wrong"])
        opts.insert(pos, item["correct"])
        u = item["usage"]
        out.append({"q": item["q"], "options": opts, "correct": pos, "explain": item["explain"],
                    "usage": {"code": u["code"], "without": u["without"], "with": u["with_"],
                              "benefit": u["benefit"]}})
    return out


if __name__ == "__main__":
    assert len(Q) == 50, len(Q)
    here = os.path.dirname(os.path.abspath(__file__))
    target = os.path.join(here, "..", "content", "dsp_fourier_transform_properties.json")
    qs = build()
    lines = ["["] + [json.dumps(q, ensure_ascii=False, separators=(",", ":")) + ("," if i < 49 else "")
                     for i, q in enumerate(qs)] + ["]"]
    with open(target, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote", os.path.normpath(target), len(qs), "questions")
